using sv_4e1fe6f70a2249c6841a4d75d2d9a92c.Models;

namespace sv_4e1fe6f70a2249c6841a4d75d2d9a92c.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] =
        [
            new Recipe(1, "Margherita Pizza", "Classic pizza with tomato, mozzarella, and basil.", 30),
            new Recipe(2, "Spaghetti Carbonara", "Creamy pasta with pancetta, egg, and pecorino.", 25),
            new Recipe(3, "Risotto alla Milanese", "Saffron-infused Arborio rice with Parmesan.", 45),
        ],
        [2] =
        [
            new Recipe(4, "Chicken Tikka Masala", "Marinated chicken in a creamy spiced tomato sauce.", 50),
            new Recipe(5, "Palak Paneer", "Cottage cheese cubes in a smooth spinach gravy.", 35),
            new Recipe(6, "Biryani", "Fragrant basmati rice layered with spiced meat and herbs.", 60),
        ],
        [3] =
        [
            new Recipe(7, "Tacos al Pastor", "Spit-grilled pork tacos with pineapple and cilantro.", 40),
            new Recipe(8, "Guacamole", "Fresh avocado dip with lime, onion, and jalapeño.", 10),
            new Recipe(9, "Enchiladas Verdes", "Corn tortillas filled with chicken and salsa verde.", 45),
        ],
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        return RecipesByCuisine.TryGetValue(cuisineId, out var recipes)
            ? recipes
            : [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@error</p>
        <button class="btn btn-outline-danger" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading…</em></p>
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    @{
        var displayed = Sort == "popular"
            ? recipes.OrderByDescending(r => r.Id)
            : recipes.OrderBy(r => r.Id);
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in displayed)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery] public string? Sort { get; set; }

    private CancellationTokenSource? cts;
    private int? loadedCuisineId;
    private List<Recipe>? recipes;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == loadedCuisineId)
        {
            return;
        }

        loadedCuisineId = CuisineId;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cancellationToken);
            recipes = result;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (parameter change or disposal) — let ComponentBase handle it.
            throw;
        }
        catch (OperationCanceledException ex)
        {
            Logger.LogWarning(ex, "Request timed out loading recipes for cuisine {CuisineId}", CuisineId);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load recipes for cuisine {CuisineId}", CuisineId);
            error = "Unable to load recipes. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

